class PersistenceSimplification(Node):
    def __init__(self, parent_node_id : str, epsilon : float, threshold_is_absolute : bool):
        super().__init__(parent_node_id, Scalar, Scalar, locals())

        self.epsilon = epsilon
        self.threshold_is_absolute = threshold_is_absolute

    @classmethod
    def guardrails(cls):
        def absolute_threshold_guardrail_function(parent_node_id, epsilon, threshold_is_absolute):
            if epsilon < 1 and threshold_is_absolute:
                raise Exception("If epsilon is less than 1, always assume that the threshold is relative unless the user explicitly stated otherwise.")

        absolute_threshold_guardrail = Guardrail(
            get_prompt("guardrails", "persistence_threshold_absolute"),
            "specified_absolute_threshold",
            "set this to True if the user explicitly stated that they wanted an absolute threshold. Set this to False otherwise.",
            absolute_threshold_guardrail_function
        )

        return [piecewise_linear_guardrail, absolute_threshold_guardrail]

    @classmethod
    def chat_description(cls):
        return "queued applying persistence simplification"

    @classmethod
    def description(cls):
        return 'Applies persistence simplification to a scalar field with a given persistence threshold' \
               'epsilon. This is based on the piecewise-linear topology.'

    @classmethod
    def param_descriptions(cls):
        return {'parent_node_id': 'The id of a node of type scalar corresponding to the scalar field '
                           'for which persistence simplification is taken.',
         'epsilon': 'The persistence threshold to apply for simplification.',
         'threshold_is_absolute': 'Set to True for the threshold to represent an absolute persistence value. Set to False '\
                                  'for the threshold to be represented as a fraction of the range, where 0 means no simplification, '\
                                  'and 1 means to simplify by the entire function range.'}

    @classmethod
    def mandatory_parameters(cls):
        return ["epsilon"]

    def _evaluation_logic(self, parent_data, time_step):

        if self.epsilon > 1 and not self.threshold_is_absolute:
            raise Exception("Cannot have an epsilon value greater than one if the threshold is absolute")

        if self.epsilon <= 0:
            raise Exception("Epsilon value must be positive.")

        ts = ttk.TTKTopologicalSimplificationByPersistence(Input=parent_data.data)
        ts.InputArray = ['POINTS', 'Scalars_']
        ts.PersistenceThreshold = self.epsilon

        if self.threshold_is_absolute:
            ts.ThresholdIsAbsolute = 1

        return Scalar(ts)

